const config = $('Config').first().json;
const list = (text, separator) =>
  String(text ?? '').split(separator).map((s) => s.trim()).filter(Boolean);
const isPlaceholder = (value) => /[<>]/.test(value);

const names = list(config.brand_names, ',');
const questions = list(config.questions, '\n');
const domain = String(config.domain ?? '')
  .trim()
  .toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/.*$/, '');

if (!names.length || names.some(isPlaceholder))
  throw new Error('Config: set brand_names to the names of your brand, with commas between them. Example: Acme, Acme CRM.');
if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(domain))
  throw new Error('Config: set domain to the domain of your site. Example: acme.com.');
if (!questions.length || questions.some(isPlaceholder))
  throw new Error('Config: set questions to the questions your buyers ask, one question on each line.');

return [{ json: { names, domain, questions } }];

const { names, domain, questions } = $('Check the Config').first().json;
// A question that has a verdict today is not asked again, so a second run on the same day costs
// nothing. A failed question has no verdict, so it is asked again.
const done = new Set(
  $input.all()
    .map((item) => item.json)
    .filter((row) => row.question && row.verdict !== 'failed')
    .map((row) => row.question),
);
return questions
  .filter((question) => !done.has(question))
  .map((question) => ({ json: { question, names, domain } }));

if ($input.first().json.result?.enabled !== false)
  throw new Error('ChatGPT memory is on: past chats change the answers. Turn it off in ChatGPT, Settings > Personalization, then execute the workflow again.');
return $('List the questions to ask').all().map((item) => ({ json: item.json }));

const { question, names, domain } = $('Stop if memory is on').all()[$itemIndex].json;
const result = $json.result;
const answer = result?.answer ?? '';
// Null when ChatGPT is signed out: its searches are then unknown, so the run measured nothing.
const queries = result?.webSearchQueries;
const returned = (result?.searches ?? []).flatMap((round) => round.results).map((r) => r.url);

// The Code sandbox has no URL global, so the host is read with a pattern.
const hostOf = (url) => /^https?:\/\/(?:www\.)?([^/?#:]+)/i.exec(url ?? '')?.[1]?.toLowerCase();
// Anchored on a dot, so notacme.com is not acme.com.
const ours = (host) => !!host && (host === domain || host.endsWith(`.${domain}`));
const cited = [...new Set((result?.references ?? []).map((r) => hostOf(r.url)).filter(Boolean))];
const named = names.some((n) => answer.toLowerCase().includes(n.toLowerCase()));

const signedOut = !$json.error && !Array.isArray(queries);
const verdict = $json.error || signedOut
  ? 'failed'
  : cited.some(ours)
    ? 'cited'
    : named
      ? 'named'
      : returned.some((url) => ours(hostOf(url)))
        ? 'in results'
        : queries.length || returned.length
          ? 'not in results'
          : 'no search';

return {
  json: {
    date: $now.toISODate(),
    question,
    verdict,
    searches: (queries ?? []).join('\n'),
    cited_domains: cited.filter((h) => !ours(h)).join(', '),
    answer: signedOut
      ? 'ChatGPT is signed out in your paired Chrome: sign in to chatgpt.com.'
      : $json.error
        ? [$json.error, $json.details].filter(Boolean).join('\n')
        : answer,
    run: $json.url ?? '',
  },
};
